import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Lesson 13: Security & Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-4/lesson-13.md","filePath":"en/modules/module-4/lesson-13.md"}'),i={name:"en/modules/module-4/lesson-13.md"};function r(n,e,d,l,h,u){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="lesson-13-security-permissions" tabindex="-1">Lesson 13: Security &amp; Permissions <a class="header-anchor" href="#lesson-13-security-permissions" aria-label="Permalink to &quot;Lesson 13: Security &amp; Permissions&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Understand the security risks when using Codex, and learn to set permissions correctly ⏱️ <strong>Estimated Time</strong>: 15 minutes 🎯 <strong>Teaching Rhythm</strong>: Explanation + hands-on demo</p></blockquote><hr><h2 id="i-why-do-we-need-permission-management" tabindex="-1">I. Why Do We Need Permission Management? <a class="header-anchor" href="#i-why-do-we-need-permission-management" aria-label="Permalink to &quot;I. Why Do We Need Permission Management?&quot;">​</a></h2><p>Codex can operate your files — read, modify, and delete. This means it has both great power and potential risks.</p><p><strong>The core purpose of permission management</strong>: Ensure Codex only operates within authorized scopes, protecting your data security.</p><hr><h2 id="ii-detailed-explanation-of-three-permission-modes" tabindex="-1">II. Detailed Explanation of Three Permission Modes <a class="header-anchor" href="#ii-detailed-explanation-of-three-permission-modes" aria-label="Permalink to &quot;II. Detailed Explanation of Three Permission Modes&quot;">​</a></h2><h3 id="_1-default-permission-recommended-for-beginners" tabindex="-1">1. Default Permission (Recommended for Beginners) <a class="header-anchor" href="#_1-default-permission-recommended-for-beginners" aria-label="Permalink to &quot;1. Default Permission (Recommended for Beginners)&quot;">​</a></h3><p>Codex asks for your approval before executing any file modifications.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Codex: I plan to create a new subfolder &quot;images&quot; in this folder and move all image files into it. Do you allow this?</span></span>
<span class="line"><span>You: [Allow / Deny]</span></span></code></pre></div><p><strong>Applicable scenarios</strong>:</p><ul><li>Just starting to use Codex</li><li>When handling important files</li><li>When you&#39;re unsure what Codex will do</li></ul><h3 id="_2-auto-review-recommended-for-advanced-users" tabindex="-1">2. Auto-Review (Recommended for Advanced Users) <a class="header-anchor" href="#_2-auto-review-recommended-for-advanced-users" aria-label="Permalink to &quot;2. Auto-Review (Recommended for Advanced Users)&quot;">​</a></h3><p>Codex can execute operations automatically, but you can review and audit afterward.</p><p><strong>Applicable scenarios</strong>:</p><ul><li>You already trust Codex&#39;s working style</li><li>When handling a large number of repetitive tasks</li><li>⚠️ It&#39;s recommended to back up important files before operations</li></ul><h3 id="_3-full-access-not-recommended" tabindex="-1">3. Full Access (Not Recommended) <a class="header-anchor" href="#_3-full-access-not-recommended" aria-label="Permalink to &quot;3. Full Access (Not Recommended)&quot;">​</a></h3><p>Codex has full read/write permission to files in your workspace.</p><p><strong>Applicable scenarios</strong>:</p><ul><li>Only enable when you fully understand the risks</li><li>Not recommended for beginners</li></ul><hr><h2 id="iii-safe-usage-guide" tabindex="-1">III. Safe Usage Guide <a class="header-anchor" href="#iii-safe-usage-guide" aria-label="Permalink to &quot;III. Safe Usage Guide&quot;">​</a></h2><h3 id="✅-what-you-should-do" tabindex="-1">✅ What You Should Do <a class="header-anchor" href="#✅-what-you-should-do" aria-label="Permalink to &quot;✅ What You Should Do&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Behavior</th><th>Explanation</th></tr></thead><tbody><tr><td>Back up important files</td><td>Back up before letting Codex operate on important files</td></tr><tr><td>Use default permissions</td><td>Keep default permissions when first starting out</td></tr><tr><td>Review results</td><td>After Codex completes a task, check whether the result is correct</td></tr><tr><td>Limit workspace</td><td>Only let Codex access the folders it needs</td></tr></tbody></table><h3 id="❌-what-you-should-not-do" tabindex="-1">❌ What You Should Not Do <a class="header-anchor" href="#❌-what-you-should-not-do" aria-label="Permalink to &quot;❌ What You Should Not Do&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Behavior</th><th>Risk</th></tr></thead><tbody><tr><td>Enter passwords, bank card info, etc.</td><td>May lead to privacy leaks</td></tr><tr><td>Give Codex full access</td><td>May accidentally delete important files</td></tr><tr><td>Don&#39;t check Codex&#39;s output</td><td>May accept incorrect results</td></tr><tr><td>Let Codex operate critical system directories</td><td>May affect normal system operation</td></tr></tbody></table><hr><h2 id="iv-hands-on-setting-permissions" tabindex="-1">IV. Hands-On: Setting Permissions <a class="header-anchor" href="#iv-hands-on-setting-permissions" aria-label="Permalink to &quot;IV. Hands-On: Setting Permissions&quot;">​</a></h2><ol><li>Open Codex&#39;s settings interface</li><li>Find &quot;Permission Management&quot; or &quot;Security Settings&quot;</li><li>Select &quot;Default Permission&quot; mode</li><li>Try having Codex perform a File Operation and observe how it asks for your confirmation.</li></ol><hr><h2 id="v-summary" tabindex="-1">V. Summary <a class="header-anchor" href="#v-summary" aria-label="Permalink to &quot;V. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Knowledge Point</th><th>Core Content</th></tr></thead><tbody><tr><td>Purpose of permission management</td><td>Ensure Codex operates within authorized scopes</td></tr><tr><td>Three modes</td><td>Default (safe), Auto-Review (efficient), Full Access (high risk)</td></tr><tr><td>Safety principles</td><td>Back up important files, limit workspace, review results</td></tr><tr><td>Sensitive information</td><td>Never enter passwords or bank card info into Codex</td></tr></tbody></table><hr><h2 id="vi-next-step" tabindex="-1">VI. Next Step <a class="header-anchor" href="#vi-next-step" aria-label="Permalink to &quot;VI. Next Step&quot;">​</a></h2><p><a href="./lesson-14.html">→ Lesson 14: Codex Skills</a></p>`,36)])])}const p=t(i,[["render",r]]);export{m as __pageData,p as default};
